        if (onNodeTrigger) {
            onNodeTrigger(hitNode.id, hitNode.ratio, hitNode.n, hitNode.d, hitNode.maxPrime);
        }

        const isPersistentlyLatched = persistentLatches.has(hitNode.id);
        const isAudioLatched = audioLatchedNodes.has(hitNode.id);

