                                        >
                                            {(['1/1', '1/2', '1/4', '1/8', '1/16', '1/32', '1/4T', '1/8T', '1/16T'] as ArpDivision[]).map(div => (
                                                <option key={div} value={div}>{div}</option>
                                            ))}
                                        </select>
                                    </div>

                                    {/* Gate Control */}
                                    <div className="flex items-center gap-1 bg-slate-900/50 rounded px-1 border border-slate-700/50">
