const App: React.FC = () => {
  const { settings, presets, updateSettings, setPreset } = useStore();

  const [masterVolume, setMasterVolume] = useState(0.8);
  const [spatialScale, setSpatialScale] = useState(1.0); 
  const [brightness, setBrightness] = useState(1.0); // Tone control

  const [activeChordIds, setActiveChordIds] = useState<string[]>([]);
  const [draggingId, setDraggingId] = useState<string | null>(null);
  const [autoScaleFactor, setAutoScaleFactor] = useState(1.0);
  const [latchMode, setLatchMode] = useState<0 | 1 | 2>(0);

  const [isSettingsOpen, setIsSettingsOpen] = useState(false);
  const [isSynthOpen, setIsSynthOpen] = useState(false);

  // Arpeggio State
  const [recordingArpId, setRecordingArpId] = useState<string | null>(null);
  const [currentArpStep, setCurrentArpStep] = useState(0);
  const [recordingFlash, setRecordingFlash] = useState<number>(0); 

  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const effectiveScale = autoScaleFactor * (settings.uiScale || 1.0);

  useEffect(() => {
    const warmup = (e: Event) => {
        audioEngine.resume().then(() => {});
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };

    window.addEventListener('pointerdown', warmup);
    window.addEventListener('keydown', warmup);
    window.addEventListener('touchstart', warmup);
    window.addEventListener('touchend', warmup);
    window.addEventListener('click', warmup);

    return () => {
        window.removeEventListener('pointerdown', warmup);
        window.removeEventListener('keydown', warmup);
        window.removeEventListener('touchstart', warmup);
        window.removeEventListener('touchend', warmup);
        window.removeEventListener('click', warmup);
    };
  }, []);

  useEffect(() => {
      document.documentElement.style.setProperty('--ui-scale', effectiveScale.toString());
  }, [effectiveScale]);

  const getSafeAreas = () => {
      if (typeof document === 'undefined') return { top: 0, right: 0, bottom: 0, left: 0 };
      const div = document.createElement('div');
      div.style.paddingTop = 'env(safe-area-inset-top)';
      div.style.paddingRight = 'env(safe-area-inset-right)';
      div.style.paddingBottom = 'env(safe-area-inset-bottom)';
      div.style.paddingLeft = 'env(safe-area-inset-left)';
      div.style.position = 'absolute';
      div.style.visibility = 'hidden';
      document.body.appendChild(div);
      const computed = getComputedStyle(div);
      const safe = {
          top: parseInt(computed.paddingTop) || 0,
          right: parseInt(computed.paddingRight) || 0,
          bottom: parseInt(computed.paddingBottom) || 0,
          left: parseInt(computed.paddingLeft) || 0
      };
      document.body.removeChild(div);
      return safe;
  };

  const applyLayout = (w: number, h: number, scale: number) => {
      const safeArea = getSafeAreas();
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;

      const marginLeft = marginPx + safeArea.left;
      const marginTop = marginPx + safeArea.top;
      // Fixed: Account for Scrollbars which are non-display functional area
      const marginRight = marginPx + safeArea.right + SCROLLBAR_WIDTH;
      const marginBottom = marginPx + safeArea.bottom + SCROLLBAR_WIDTH;
      const baseGap = marginPx; 

      const audioStackWidth = 500 * scale; 
      const arpBarWidth = 350 * scale;
      const settingsGroupWidth = 170; 
      const settingsGroupHeight = 40; 
      const largeBtn = 80 * scale; 
      const limitBarWidth = 24 + (72 * scale); 

      const newPos = { ...settings.uiPositions };
      const requiredWidth = arpBarWidth + audioStackWidth + settingsGroupWidth + (baseGap * 4);
      const shouldHideExtras = w < requiredWidth;

      if (shouldHideExtras) {
          newPos.arpeggioBar = { x: -9999, y: -9999 };
          newPos.layers = { x: -9999, y: -9999 };
          newPos.volume = { x: (w / 2) - (audioStackWidth / 2), y: marginTop };
      } else {
          newPos.arpeggioBar = { x: marginLeft, y: marginTop };
          const volX = w - marginRight - settingsGroupWidth - baseGap - audioStackWidth;
          newPos.volume = { x: volX, y: marginTop };
          const limitBarX = w - marginRight - limitBarWidth;
          const layersY = marginTop + settingsGroupHeight + (20 * scale); 
          newPos.layers = { x: limitBarX, y: layersY };
      }

      newPos.space = { x: -9999, y: -9999 };

      // LATCH CLUSTER
      const buttonsX = w - marginRight - largeBtn;
      const btnGap = 10 * scale;
      const panicY = h - marginBottom - largeBtn;
      const offY = panicY - largeBtn - btnGap;
      const latchY = offY - largeBtn - btnGap;
      const bendY = latchY - largeBtn - btnGap;

      newPos.panic = { x: buttonsX, y: panicY };
      newPos.off = { x: buttonsX, y: offY };
      newPos.latch = { x: buttonsX, y: latchY };
      newPos.bend = { x: buttonsX, y: bendY };

      // BOTTOM CONTROLS
      const bottomY = h - marginBottom - largeBtn; 
      let currentX = marginLeft;
      newPos.center = { x: currentX, y: bottomY };
      currentX += (largeBtn + baseGap); 
      if (settings.showIncreaseDepthButton) {
          newPos.depth = { x: currentX, y: bottomY };
          currentX += (largeBtn + baseGap);
          newPos.decreaseDepth = { x: currentX, y: bottomY };
          currentX += (largeBtn + baseGap);
      }
      currentX += (10 * scale); 
      newPos.chords = { x: currentX, y: bottomY };
      return newPos;
  };

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;
        const shortEdge = Math.min(w, h);
        const newAutoScale = shortEdge / REFERENCE_SHORT_EDGE;
        setAutoScaleFactor(newAutoScale);
        const newEffectiveScale = newAutoScale * (settings.uiScale || 1.0);
        updateSettings(prev => ({ ...prev, uiPositions: applyLayout(w, h, newEffectiveScale) }));
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale, settings.uiEdgeMargin, settings.showIncreaseDepthButton]); 

  useEffect(() => { audioEngine.setMasterVolume(masterVolume); }, [masterVolume]);
  useEffect(() => { audioEngine.setGlobalSpatialScale(spatialScale); }, [spatialScale]);
  useEffect(() => { audioEngine.setGlobalBrightness(brightness); }, [brightness]);

  const handleLimitInteraction = (limit: number) => {
    if (settings.layerOrder[settings.layerOrder.length - 1] !== limit) {
      const newOrder = settings.layerOrder.filter(l => l !== limit);
      newOrder.push(limit);
      updateSettings(prev => ({ ...prev, layerOrder: newOrder }));
    }
  };

  const handlePanic = () => {
    audioEngine.stopAll(); 
    arpeggiatorService.stop();
    midiService.panic();
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]); 
    setLatchMode(0);
    setRecordingArpId(null);
    updateSettings(prev => ({ ...prev, arpeggios: prev.arpeggios.map(a => ({ ...a, isPlaying: false })) }));
    setIsSettingsOpen(false);
    setIsSynthOpen(false);
  };

  const handleOff = () => {
    diamondRef.current?.clearLatches(); 
    setActiveChordIds([]);
    setLatchMode(0);
    setRecordingArpId(null);
  };

  const handleLatchToggle = () => {
      setLatchMode(prev => {
          const next = prev + 1;
          if (next > 2) {
              diamondRef.current?.clearLatches();
              return 0;
          }
          return next as 0 | 1 | 2;
      });
  };

  const handleBendToggle = () => {
      if (latchMode === 1) return;
      updateSettings(prev => ({ ...prev, isPitchBendEnabled: !prev.isPitchBendEnabled }));
  };

  const handleCenter = () => diamondRef.current?.centerView();
  const handleIncreaseDepth = () => diamondRef.current?.increaseDepth();
  const handleDecreaseDepth = () => diamondRef.current?.decreaseDepth();

  const handleAddChord = () => {
      if (diamondRef.current) {
          const latchedNodes = diamondRef.current.getLatchedNodes();
          if (latchedNodes.length === 0) return;
          let slotIndex = settings.savedChords.findIndex(c => c.nodes.length === 0);
          if (slotIndex === -1) slotIndex = settings.savedChords.findIndex(c => !c.visible);
          if (slotIndex !== -1) {
              const newChords = [...settings.savedChords];
              const simplifiedNodes = latchedNodes.map(n => ({ id: n.id, n: n.n, d: n.d }));
              newChords[slotIndex] = { ...newChords[slotIndex], nodes: simplifiedNodes, visible: true, position: { x: 0, y: 0 } };
              updateSettings(prev => ({ ...prev, savedChords: newChords }));
          }
      }
  };

  const toggleChord = (id: string) => setActiveChordIds(prev => prev.includes(id) ? prev.filter(c => c !== id) : [...prev, id]);
  const handleUiPositionUpdate = (key: keyof AppSettings['uiPositions'], pos: XYPos) => updateSettings(prev => ({ ...prev, uiPositions: { ...prev.uiPositions, [key]: pos } }));

  const handleArpToggle = (id: string) => {
      const arp = settings.arpeggios.find(a => a.id === id);
      if (!arp) return;
      if (recordingArpId === id) { setRecordingArpId(null); return; }
      if (recordingArpId) { setRecordingArpId(id); return; }
      if (arp.steps.length === 0) {
          setRecordingArpId(id);
          updateSettings(prev => ({ ...prev, arpeggios: prev.arpeggios.map(a => a.id === id ? { ...a, isPlaying: false } : a) }));
          return;
      }
      const newIsPlaying = !arp.isPlaying;
      const newArps = settings.arpeggios.map(a => a.id === id ? { ...a, isPlaying: newIsPlaying } : { ...a, isPlaying: false });
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
      if (newIsPlaying) arpeggiatorService.start(arp.steps, arp.config, settings.arpBpm, (step) => setCurrentArpStep(step));
      else arpeggiatorService.stop();
  };

  const handleArpRecordNote = (nodeId: string, ratio: number, n?: number, d?: number, limit?: number) => {
      if (!recordingArpId) return;
      const arpIndex = settings.arpeggios.findIndex(a => a.id === recordingArpId);
      if (arpIndex === -1) return;
      const currentSteps = settings.arpeggios[arpIndex].steps;
      if (currentSteps.length >= 32) { setRecordingArpId(null); return; }
      const newStep: ArpeggioStep = { nodeId, ratio, n, d, limit, muted: false };
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = { ...newArps[arpIndex], steps: [...currentSteps, newStep] };
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpPatternUpdate = (arpId: string, steps: ArpeggioStep[]) => {
      const arpIndex = settings.arpeggios.findIndex(a => a.id === arpId);
      if (arpIndex === -1) return;
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = { ...newArps[arpIndex], steps: steps };
      if (newArps[arpIndex].isPlaying && steps.length === 0) { newArps[arpIndex].isPlaying = false; arpeggiatorService.stop(); }
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
  };

  const handleArpBpmChange = (bpm: number) => { updateSettings(prev => ({ ...prev, arpBpm: bpm })); arpeggiatorService.updateBpm(bpm); };
  const handleArpRowConfigChange = (arpId: string, partial: Partial<ArpConfig>) => {
      const arpIndex = settings.arpeggios.findIndex(a => a.id === arpId);
      if (arpIndex === -1) return;
      const newArps = [...settings.arpeggios];
      newArps[arpIndex] = { ...newArps[arpIndex], config: { ...newArps[arpIndex].config, ...partial } };
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
      if (newArps[arpIndex].isPlaying) arpeggiatorService.start(newArps[arpIndex].steps, newArps[arpIndex].config, settings.arpBpm, (step) => setCurrentArpStep(step));
  };

  const handlePlayAll = () => {
      const newArps = settings.arpeggios.map(a => ({ ...a, isPlaying: a.steps.length > 0 }));
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
      const firstValid = newArps.find(a => a.steps.length > 0);
      if (firstValid) arpeggiatorService.start(firstValid.steps, firstValid.config, settings.arpBpm, (step) => setCurrentArpStep(step));
  };

  const handleStopAll = () => {
      const newArps = settings.arpeggios.map(a => ({ ...a, isPlaying: false }));
      updateSettings(prev => ({ ...prev, arpeggios: newArps }));
      arpeggiatorService.stop();
  };

  useEffect(() => {
      const handleKeyDown = (e: KeyboardEvent) => {
          if (e.key === 'Escape' && (isSettingsOpen || isSynthOpen)) { setIsSettingsOpen(false); setIsSynthOpen(false); return; }
          const target = e.target as HTMLElement;
          if (target.tagName === 'INPUT' || target.tagName === 'SELECT' || target.tagName === 'TEXTAREA') return;
          if (!settings.enableKeyboardShortcuts) return;
          const key = e.key.toLowerCase();
          const map = settings.keyMappings;
          if ([map.latch, map.volumeUp, map.volumeDown, map.spatialScaleUp, map.spatialScaleDown].map(k => k.toLowerCase()).includes(key)) e.preventDefault();
          if (key === map.latch.toLowerCase()) handleLatchToggle();
          else if (key === map.panic.toLowerCase()) handlePanic();
          else if (key === map.center.toLowerCase()) handleCenter();
          else if (key === map.settings.toLowerCase()) { setIsSettingsOpen(prev => !prev); if(isSynthOpen) setIsSynthOpen(false); }
          else if (key === map.synth.toLowerCase()) { setIsSynthOpen(prev => !prev); if(isSettingsOpen) setIsSettingsOpen(false); }
          else if (key === map.off.toLowerCase()) handleOff();
          else if (key === map.bend.toLowerCase()) handleBendToggle();
          else if (key === map.addChord.toLowerCase()) handleAddChord();
          else if (key === map.increaseDepth.toLowerCase()) handleIncreaseDepth();
          else if (key === map.decreaseDepth.toLowerCase()) handleDecreaseDepth();
          else if (key === map.volumeUp.toLowerCase()) setMasterVolume(v => Math.min(1.0, v + 0.05));
          else if (key === map.volumeDown.toLowerCase()) setMasterVolume(v => Math.max(0.0, v - 0.05));
          else if (key === map.spatialScaleUp.toLowerCase()) setSpatialScale(s => Math.min(2.0, s + 0.05));
          else if (key === map.spatialScaleDown.toLowerCase()) setSpatialScale(s => Math.max(0.0, s - 0.05));
      };
      window.addEventListener('keydown', handleKeyDown);
      return () => window.removeEventListener('keydown', handleKeyDown);
  }, [isSettingsOpen, isSynthOpen, settings.enableKeyboardShortcuts, settings.keyMappings, latchMode]);

  const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
  const safeArea = getSafeAreas();
  const leftOffset = `calc(${marginPx}px + ${safeArea.left}px)`;
  const rightOffset = `calc(${marginPx}px + ${safeArea.right}px + ${SCROLLBAR_WIDTH}px)`;
  const headerTop = `calc(${marginPx}px + ${safeArea.top}px)`;
  const headerBtnClass = "bg-slate-900/50 hover:bg-slate-800 px-3 py-1 rounded-xl backdrop-blur-sm transition border border-slate-700/50 h-8 flex items-center text-[10px] font-bold text-slate-400 uppercase tracking-widest hover:text-white shadow-lg";

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <div className="absolute z-50 pointer-events-none" style={{ top: headerTop, left: leftOffset }}><h1 className="text-sm font-bold tracking-widest text-slate-500 opacity-20 leading-none">PRISMATONAL</h1></div>
      <div className="absolute z-50 flex gap-2 pointer-events-auto" style={{ top: headerTop, right: rightOffset }}>
          <button onClick={() => setIsSettingsOpen(true)} className={headerBtnClass}>Settings</button>
          <button onClick={() => setIsSynthOpen(true)} className={headerBtnClass}>Synth</button>
      </div>
      <TonalityDiamond ref={diamondRef} settings={settings} updateSettings={updateSettings} audioEngine={audioEngine} onLimitInteraction={handleLimitInteraction} activeChordIds={activeChordIds} uiUnlocked={settings.uiUnlocked} latchMode={latchMode} globalScale={effectiveScale} onNodeTrigger={handleArpRecordNote} />
      <FloatingControls volume={masterVolume} setVolume={setMasterVolume} spatialScale={spatialScale} setSpatialScale={setSpatialScale} brightness={brightness} setBrightness={setBrightness} onPanic={handlePanic} onOff={handleOff} onLatch={handleLatchToggle} latchMode={latchMode} onBend={handleBendToggle} isBendEnabled={settings.isPitchBendEnabled} onCenter={handleCenter} onIncreaseDepth={handleIncreaseDepth} onDecreaseDepth={handleDecreaseDepth} onAddChord={handleAddChord} toggleChord={toggleChord} activeChordIds={activeChordIds} savedChords={settings.savedChords} chordShortcutSizeScale={settings.chordShortcutSizeScale} showIncreaseDepthButton={settings.showIncreaseDepthButton} uiUnlocked={settings.uiUnlocked} uiPositions={settings.uiPositions} updatePosition={handleUiPositionUpdate} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} arpeggios={settings.arpeggios} arpBpm={settings.arpBpm} onArpToggle={handleArpToggle} onArpBpmChange={handleArpBpmChange} onArpRowConfigChange={handleArpRowConfigChange} onArpPatternUpdate={handleArpPatternUpdate} recordingArpId={recordingArpId} currentArpStep={currentArpStep} onPlayAll={handlePlayAll} onStopAll={handleStopAll} />
      <LimitLayerControls settings={settings} updateSettings={updateSettings} draggingId={draggingId} setDraggingId={setDraggingId} uiScale={effectiveScale} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
    </div>
  );
};

export default App;

import React, { useState, useEffect } from 'react';
import { ChordDefinition, XYPos, AppSettings, ArpeggioDefinition, ArpConfig, ArpDirection, ArpDivision, ArpeggioStep } from '../types';
import { MARGIN_3MM, SCROLLBAR_WIDTH, DEFAULT_COLORS } from '../constants';

interface Props {
  volume: number;
  setVolume: (v: number) => void;
  spatialScale: number;
  setSpatialScale: (v: number) => void;
  brightness: number;
  setBrightness: (v: number) => void;

  onPanic: () => void;
  onOff: () => void;
  onLatch: () => void;
  latchMode: 0 | 1 | 2;
  onBend: () => void;
  isBendEnabled: boolean;
  onCenter: () => void;
  onIncreaseDepth: () => void;
  onDecreaseDepth: () => void;
  onAddChord: () => void;
  toggleChord: (id: string) => void;
  activeChordIds: string[];
  savedChords: ChordDefinition[];
  chordShortcutSizeScale: number;
  showIncreaseDepthButton: boolean;
  uiUnlocked: boolean;
  uiPositions: AppSettings['uiPositions'];
  updatePosition: (key: keyof AppSettings['uiPositions'], pos: XYPos) => void;
  draggingId: string | null;
  setDraggingId: (id: string | null) => void;
  uiScale?: number;

  // Arp Props
  arpeggios?: ArpeggioDefinition[];
  arpBpm?: number;
  onArpToggle?: (id: string) => void;
  onArpBpmChange?: (bpm: number) => void;
  onArpRowConfigChange?: (arpId: string, config: Partial<ArpConfig>) => void;
  onArpPatternUpdate?: (arpId: string, steps: ArpeggioStep[]) => void;
  recordingArpId?: string | null; 
  currentArpStep?: number;
  recordingFlash?: number; // Timestamp trigger

  // New Control Handlers
  onPlayAll?: () => void;
  onStopAll?: () => void;
}

// Helper to determine color based on prime limit
const getMaxPrime = (n: number): number => {
  let temp = n;
  while (temp % 2 === 0 && temp > 1) temp /= 2;
  if (temp === 1) return 1;
  let maxP = 1;
  let d = 3;
  while (d * d <= temp) {
    while (temp % d === 0) { maxP = d; temp /= d; }
    d += 2;
  }
  if (temp > 1) maxP = temp;
  return maxP;
};

const FloatingControls: React.FC<Props> = ({ 
  volume, setVolume, spatialScale, setSpatialScale, brightness, setBrightness,
  onPanic, onOff, onLatch, latchMode, onBend, isBendEnabled, onCenter, onIncreaseDepth, onDecreaseDepth, onAddChord, toggleChord,
  activeChordIds, savedChords, chordShortcutSizeScale,
  showIncreaseDepthButton, uiUnlocked, uiPositions, updatePosition,
  draggingId, setDraggingId,
  uiScale = 1.0,
  arpeggios = [], arpBpm = 120, onArpToggle, onArpBpmChange, onArpRowConfigChange, onArpPatternUpdate, recordingArpId, currentArpStep, recordingFlash = 0,
  onPlayAll, onStopAll
}) => {

  const [showSequencer, setShowSequencer] = useState(false);
  const [isFlashingRed, setIsFlashingRed] = useState(false);
  const [isArpBarHovered, setIsArpBarHovered] = useState(false);

  useEffect(() => {
      if (recordingFlash > 0) {
          setIsFlashingRed(true);
          const t = setTimeout(() => setIsFlashingRed(false), 200);
          return () => clearTimeout(t);
      }
  }, [recordingFlash]);

  const handleDrag = (e: React.PointerEvent, key: keyof AppSettings['uiPositions']) => {
    if (!uiUnlocked) return;
    if (draggingId !== null && draggingId !== key) return;

    const el = e.currentTarget as HTMLElement;
    const startX = e.clientX;
    const startY = e.clientY;
    const initialLeft = uiPositions[key as keyof typeof uiPositions].x;
    const initialTop = uiPositions[key as keyof typeof uiPositions].y;

    el.setPointerCapture(e.pointerId);
    setDraggingId(key);

    const onMove = (evt: PointerEvent) => {
        const deltaX = evt.clientX - startX;
        const deltaY = evt.clientY - startY;
        let newX = initialLeft + deltaX;
        let newY = initialTop + deltaY;
        const maxX = window.innerWidth - el.offsetWidth - MARGIN_3MM - SCROLLBAR_WIDTH;
        const maxY = window.innerHeight - el.offsetHeight - MARGIN_3MM - SCROLLBAR_WIDTH;
        const minX = MARGIN_3MM;
        const minY = MARGIN_3MM;
        newX = Math.max(minX, Math.min(newX, maxX));
        newY = Math.max(minY, Math.min(newY, maxY));
        updatePosition(key, { x: newX, y: newY });
    };

    const onUp = () => {
        setDraggingId(null);
        window.removeEventListener('pointermove', onMove);
        window.removeEventListener('pointerup', onUp);
        window.removeEventListener('pointercancel', onUp);
    };

    window.addEventListener('pointermove', onMove);
    window.addEventListener('pointerup', onUp);
    window.addEventListener('pointercancel', onUp);
  };

  const largeBtnSize = 80 * uiScale;
  const baseSize = largeBtnSize; 
  const chordSize = baseSize * chordShortcutSizeScale;
  const stackWidth = 500 * uiScale; 

  const draggableStyle = (key: string) => ({
      left: uiPositions[key as keyof typeof uiPositions].x,
      top: uiPositions[key as keyof typeof uiPositions].y,
      touchAction: 'none' as React.CSSProperties['touchAction'],
  });

  const handleButtonPress = (e: React.PointerEvent, key: keyof AppSettings['uiPositions'], action: () => void) => {
      e.stopPropagation();
      if (uiUnlocked) { handleDrag(e, key); } else { action(); }
  };

  const getLatchStyle = () => {
      const base = "absolute rounded-full flex items-center justify-center font-bold uppercase tracking-wider backdrop-blur transition-all z-[150] select-none shadow-lg";
      const unlocked = uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : '';
      if (latchMode === 1) return `${base} ${unlocked} bg-green-500 text-white border-2 border-green-300 shadow-[0_0_20px_rgba(34,197,94,0.8)]`;
      else if (latchMode === 2) return `${base} ${unlocked} bg-green-900/60 text-green-400 border-2 border-green-400 ring-4 ring-green-500/30 animate-pulse shadow-[0_0_15px_rgba(34,197,94,0.4)]`;
      else return `${base} ${unlocked} bg-green-900/40 border-2 border-green-500/50 text-green-500 hover:bg-green-800/60 active:bg-green-600 active:text-white shadow-[0_0_15px_rgba(34,197,94,0.2)]`;
  };

  const isAnyArpPlaying = arpeggios.some(a => a.isPlaying);
  const getBpmLightClass = () => {
      if (isFlashingRed) return 'bg-red-500 shadow-[0_0_10px_red]';
      if (isAnyArpPlaying) {
          const tick = Math.floor(Date.now() / (30000 / (arpBpm || 120)));
          return tick % 2 === 0 ? 'bg-green-500 shadow-[0_0_5px_lime]' : 'bg-slate-800';
      }
      return 'bg-slate-800';
  };

  const isBendLocked = latchMode === 1;

  return (
    <>
      <style>{`
        .prismatonal-slider::-webkit-slider-thumb { -webkit-appearance: none; appearance: none; width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        .prismatonal-slider::-moz-range-thumb { width: 12px; height: 12px; border-radius: 50%; background: currentColor; cursor: pointer; border: 2px solid white; box-shadow: 0 0 5px rgba(0,0,0,0.5); }
        input[type=number]::-webkit-inner-spin-button, input[type=number]::-webkit-outer-spin-button { -webkit-appearance: none; margin: 0; }
        .no-spinner { -moz-appearance: textfield; }
      `}</style>

      {/* Unified Audio Stack */}
      <div className={`absolute bg-slate-900/50 rounded-xl flex flex-col p-1.5 gap-0.5 backdrop-blur-sm border border-slate-700/50 transition-colors z-[150] shadow-2xl ${uiUnlocked ? 'cursor-move ring-2 ring-yellow-500/50' : ''}`} style={{ ...draggableStyle('volume'), width: stackWidth }} onPointerDown={(e) => handleDrag(e, 'volume')}>
        <div className="flex items-center gap-2 w-full h-5">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={{ fontSize: 10 * uiScale, width: 30 * uiScale }}>Vol</span>
             <div className="flex-1 min-w-0 flex items-center">
                <input type="range" min="0" max="1" step="0.01" value={volume} onChange={(e) => setVolume(parseFloat(e.target.value))} disabled={uiUnlocked} className={`prismatonal-slider w-full rounded-lg appearance-none text-green-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`} style={{ height: 4 * uiScale, background: `linear-gradient(to right, #22c55e 0%, #22c55e ${volume * 100}%, #334155 ${volume * 100}%, #334155 100%)` }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} />
             </div>
        </div>
        <div className="flex items-center gap-2 w-full h-5">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={{ fontSize: 10 * uiScale, width: 30 * uiScale }}>Rev</span>
             <div className="flex-1 min-w-0 flex items-center">
                <input type="range" min="0" max="2" step="0.01" value={spatialScale} onChange={(e) => setSpatialScale(parseFloat(e.target.value))} disabled={uiUnlocked} className={`prismatonal-slider w-full rounded-lg appearance-none text-blue-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`} style={{ height: 4 * uiScale, background: `linear-gradient(to right, #3b82f6 0%, #3b82f6 ${(spatialScale/2) * 100}%, #334155 ${(spatialScale/2) * 100}%, #334155 100%)` }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} />
             </div>
        </div>
        <div className="flex items-center gap-2 w-full h-5">
             <span className="font-bold text-slate-400 select-none uppercase tracking-widest text-right flex-shrink-0" style={{ fontSize: 10 * uiScale, width: 30 * uiScale }}>Ton</span>
             <div className="flex-1 min-w-0 flex items-center">
                <input type="range" min="0" max="1" step="0.01" value={brightness} onChange={(e) => setBrightness(parseFloat(e.target.value))} disabled={uiUnlocked} className={`prismatonal-slider w-full rounded-lg appearance-none text-yellow-500 ${uiUnlocked ? 'cursor-move opacity-50' : 'cursor-pointer'}`} style={{ height: 4 * uiScale, background: `linear-gradient(to right, #eab308 0%, #eab308 ${brightness * 100}%, #334155 ${brightness * 100}%, #334155 100%)` }} onPointerDown={(e) => !uiUnlocked && e.stopPropagation()} />
             </div>
        </div>
      </div>

