export interface TonalityDiamondHandle {
  clearLatches: () => void;
  centerView: () => void;
  increaseDepth: () => void;
  decreaseDepth: () => void;
  getLatchedNodes: () => LatticeNode[];
}

interface ActiveCursor {
  pointerId: number;
  currentX: number;
  currentY: number;
  originNodeId: string | null; 
  hoverNodeId: string | null;
  hasMoved: boolean;
  hitNodesThisSwipe: Set<string>; // New: Prevent re-sounding/re-toggling same node in one swipe
}

const GRID_CELL_SIZE = 100; 

const TonalityDiamond = forwardRef<TonalityDiamondHandle, Props>((props, ref) => {
  const { settings, updateSettings, audioEngine, onLimitInteraction, activeChordIds, uiUnlocked, latchMode, globalScale = 1.0, onNodeTrigger } = props;

  const scrollContainerRef = useRef<HTMLDivElement>(null);
  const staticCanvasRef = useRef<HTMLCanvasElement>(null); 
  const dynamicCanvasRef = useRef<HTMLCanvasElement>(null); 
  const [data, setData] = useState<{ nodes: LatticeNode[], lines: LatticeLine[] }>({ nodes: [], lines: [] });
  const [isGenerating, setIsGenerating] = useState(false);
  const [isInitialLoad, setIsInitialLoad] = useState(true);
  const [dynamicSize, setDynamicSize] = useState(2000);

  const [activeCursors, setActiveCursors] = useState<Map<number, ActiveCursor>>(new Map());
  const [persistentLatches, setPersistentLatches] = useState<Map<string, string>>(new Map());

  const nodeMap = useMemo(() => new Map(data.nodes.map(n => [n.id, n])), [data.nodes]);
  const audioLatchedNodes = useMemo(() => {
      const effective = new Map<string, string>(persistentLatches);
      activeChordIds.forEach(id => {
        const chord = settings.savedChords.find(c => c.id === id);
        chord?.nodes.forEach(n => !effective.has(n.id) && effective.set(n.id, n.id));
      });
      return effective;
  }, [persistentLatches, activeChordIds, settings.savedChords]);

  const activeCursorsRef = useRef(activeCursors);
  const nodeMapRef = useRef(nodeMap);
  useEffect(() => { activeCursorsRef.current = activeCursors; }, [activeCursors]);
  useEffect(() => { nodeMapRef.current = nodeMap; }, [nodeMap]);

  useImperativeHandle(ref, () => ({
    clearLatches: () => setPersistentLatches(new Map()),
    centerView: () => { centerScroll(); },
    increaseDepth: () => {}, // Summary logic...
    decreaseDepth: () => {},
    getLatchedNodes: () => Array.from(audioLatchedNodes.keys()).map(id => nodeMap.get(id)).filter(n => !!n) as LatticeNode[]
  }));

  const centerScroll = () => {
    if (scrollContainerRef.current) {
        const center = dynamicSize / 2;
        scrollContainerRef.current.scrollLeft = center - scrollContainerRef.current.clientWidth / 2;
        scrollContainerRef.current.scrollTop = center - scrollContainerRef.current.clientHeight / 2;
    }
  };

  const getHitNode = (clientX: number, clientY: number): LatticeNode | null => {
      if (!dynamicCanvasRef.current) return null;
      const rect = dynamicCanvasRef.current.getBoundingClientRect();
      const x = clientX - rect.left;
      const y = clientY - rect.top;
      const spacing = settings.buttonSpacingScale * globalScale;
      const baseRadius = (60 * settings.buttonSizeScale * globalScale) / 2;
      const center = dynamicSize / 2;

      for (const node of data.nodes) {
          const nx = node.x * spacing + center;
          const ny = node.y * spacing + center;
          const vis = settings.limitVisuals?.[node.limitTop] || { size: 1 };
          const r = baseRadius * vis.size;
          if (Math.abs(x - nx) < r && Math.abs(y - ny) < r) {
              if (Math.pow(x - nx, 2) + Math.pow(y - ny, 2) < r * r) return node;
          }
      }
      return null;
  };

  const handlePointerDown = (e: React.PointerEvent) => {
      if (uiUnlocked) return;
      audioEngine.resume();
      (e.target as HTMLElement).setPointerCapture(e.pointerId);
      const hit = getHitNode(e.clientX, e.clientY);
      const hitSet = new Set<string>();
      if (hit) hitSet.add(hit.id);

      setActiveCursors(prev => {
          const next = new Map(prev);
          next.set(e.pointerId, {
              pointerId: e.pointerId, currentX: e.clientX, currentY: e.clientY,
              originNodeId: hit?.id || null, hoverNodeId: hit?.id || null,
              hasMoved: false, hitNodesThisSwipe: hitSet
          });
          return next;
      });

      if (hit) {
          if (latchMode === 1) {
              setPersistentLatches(prev => {
                  const next = new Map(prev);
                  if (next.has(hit.id)) next.delete(hit.id);
                  else next.set(hit.id, hit.id);
                  return next;
              });
          } else {
              const voiceId = `cursor-${e.pointerId}-${hit.id}`;
              audioEngine.startVoice(voiceId, hit.ratio, settings.baseFrequency, latchMode === 2 ? 'latch' : 'normal');
          }
      }
  };

  const handlePointerMove = (e: React.PointerEvent) => {
    const cursor = activeCursorsRef.current.get(e.pointerId);
    if (!cursor || uiUnlocked) return;

    const hit = getHitNode(e.clientX, e.clientY);
    if (hit && !cursor.hitNodesThisSwipe.has(hit.id)) {
        cursor.hitNodesThisSwipe.add(hit.id);
        if (latchMode === 1) {
            setPersistentLatches(prev => {
                const next = new Map(prev);
                if (next.has(hit.id)) next.delete(hit.id);
                else next.set(hit.id, hit.id);
                return next;
            });
        } else if (!audioLatchedNodes.has(hit.id)) {
            audioEngine.startVoice(`cursor-${e.pointerId}-${hit.id}`, hit.ratio, settings.baseFrequency, 'strum');
        }
    }

    // Pitch bend logic disabled in latch mode 1
    if (cursor.originNodeId && settings.isPitchBendEnabled && latchMode !== 1) {
        // Glide logic...
    }
  };

  const handlePointerUp = (e: React.PointerEvent) => {
      const cursor = activeCursorsRef.current.get(e.pointerId);
      if (cursor && cursor.originNodeId && latchMode === 0) {
          audioEngine.stopVoice(`cursor-${e.pointerId}-${cursor.originNodeId}`);
      }
      setActiveCursors(prev => { const next = new Map(prev); next.delete(e.pointerId); return next; });
  };

  // Rendering and generation logic summarized...
  useEffect(() => {
    setIsGenerating(true);
    const timer = setTimeout(() => {
        const result = generateLattice(settings);
        setData(result);
        setIsGenerating(false);
    }, 50);
    return () => clearTimeout(timer);
  }, [JSON.stringify(settings.limitDepths)]);

  const prevAudioLatchedRef = useRef<Map<string, string>>(new Map());
  useEffect(() => {
      const current = audioLatchedNodes;
      const prev = prevAudioLatchedRef.current;
      current.forEach((_, id) => {
          if (!prev.has(id)) {
              const n = nodeMap.get(id);
              if (n) audioEngine.startVoice(`node-${id}`, n.ratio, settings.baseFrequency, 'latch');
          }
      });
      prev.forEach((_, id) => {
          if (!current.has(id)) audioEngine.stopVoice(`node-${id}`);
      });
      prevAudioLatchedRef.current = current;
  }, [audioLatchedNodes, nodeMap, settings.baseFrequency]);

  return (
    <div ref={scrollContainerRef} className="w-full h-full overflow-auto bg-slate-950 relative" onPointerDown={handlePointerDown} onPointerMove={handlePointerMove} onPointerUp={handlePointerUp}>
        <div className="relative" style={{ width: dynamicSize, height: dynamicSize, backgroundColor: 'black' }}>
           <canvas ref={staticCanvasRef} className="absolute top-0 left-0 z-[10]" style={{ width: '100%', height: '100%' }} />
           <canvas ref={dynamicCanvasRef} className="absolute top-0 left-0 z-[20]" style={{ width: '100%', height: '100%' }} />
        </div>
    </div>
  );
});

