  const [isSynthOpen, setIsSynthOpen] = useState(false);
  const diamondRef = useRef<TonalityDiamondHandle>(null);

  const applyLayout = (w: number, h: number, scale: number) => {
      const marginPx = (settings.uiEdgeMargin || 4) * PIXELS_PER_MM;
      const rightOff = marginPx + SCROLLBAR_WIDTH;
      const bottomOff = marginPx + SCROLLBAR_WIDTH;
      const largeBtn = 80 * scale; 
      const newPos = { ...settings.uiPositions };

      newPos.volume = { x: (w / 2) - (250 * scale), y: marginPx };
      newPos.layers = { x: w - rightOff - (72 * scale) - 24, y: marginPx + 60 };

      const buttonsX = w - rightOff - largeBtn;
      const btnGap = 10 * scale;
      newPos.panic = { x: buttonsX, y: h - bottomOff - largeBtn };
      newPos.off = { x: buttonsX, y: newPos.panic.y - largeBtn - btnGap };
      newPos.latch = { x: buttonsX, y: newPos.off.y - largeBtn - btnGap };
      newPos.bend = { x: buttonsX, y: newPos.latch.y - largeBtn - btnGap };

      newPos.center = { x: marginPx, y: h - bottomOff - largeBtn };
      newPos.chords = { x: marginPx + largeBtn + 20, y: h - bottomOff - largeBtn };

      return newPos;
  };

  useEffect(() => {
    const handleResize = () => {
        const w = document.documentElement.clientWidth;
        const h = document.documentElement.clientHeight;
        const scale = (Math.min(w, h) / 1080) * (settings.uiScale || 1.0);
        updateSettings(prev => ({ ...prev, uiPositions: applyLayout(w, h, scale) }));
    };
    handleResize();
    window.addEventListener('resize', handleResize);
    return () => window.removeEventListener('resize', handleResize);
  }, [settings.uiScale]);

  return (
    <div className="relative w-screen h-screen overflow-hidden bg-slate-900 font-sans text-white">
      <TonalityDiamond ref={diamondRef} settings={settings} updateSettings={updateSettings} audioEngine={audioEngine} onLimitInteraction={() => {}} activeChordIds={[]} uiUnlocked={settings.uiUnlocked} latchMode={latchMode} />
      <FloatingControls volume={0.8} setVolume={() => {}} spatialScale={1.0} setSpatialScale={() => {}} brightness={1.0} setBrightness={() => {}} onPanic={() => audioEngine.stopAll()} onOff={() => { setLatchMode(0); diamondRef.current?.clearLatches(); }} onLatch={() => setLatchMode(l => (l + 1) % 3 as any)} latchMode={latchMode} onBend={() => updateSettings(s => ({ ...s, isPitchBendEnabled: !s.isPitchBendEnabled }))} isBendEnabled={settings.isPitchBendEnabled} onCenter={() => diamondRef.current?.centerView()} onIncreaseDepth={() => {}} onDecreaseDepth={() => {}} onAddChord={() => {}} toggleChord={() => {}} activeChordIds={[]} savedChords={settings.savedChords} chordShortcutSizeScale={settings.chordShortcutSizeScale} showIncreaseDepthButton={true} uiUnlocked={settings.uiUnlocked} uiPositions={settings.uiPositions} updatePosition={(k, p) => updateSettings(s => ({ ...s, uiPositions: { ...s.uiPositions, [k]: p } }))} draggingId={null} setDraggingId={() => {}} />
      <LimitLayerControls settings={settings} updateSettings={updateSettings} draggingId={null} setDraggingId={() => {}} />
      <SettingsModal isOpen={isSettingsOpen} onClose={() => setIsSettingsOpen(false)} settings={settings} updateSettings={updateSettings} />
      <SynthControls isOpen={isSynthOpen} onClose={() => setIsSynthOpen(false)} presets={presets} onChange={setPreset} />
      <div className="absolute top-4 right-4 flex gap-2">
        <button onClick={() => setIsSettingsOpen(true)} className="bg-slate-800 p-2 rounded">Settings</button>
        <button onClick={() => setIsSynthOpen(true)} className="bg-slate-800 p-2 rounded">Synth</button>
      </div>
    </div>
  );
};

export default App;

